import pandas as pd
res=pd.read_csv('/app/data/restaurants/clean_restaurant_2022.csv')

def pick(city, cuisine, n=3):
    subset=res[res['City']==city]
    match=subset[subset['Cuisines'].str.contains(cuisine, case=False, na=False)]
    match=match.sort_values(['Aggregate Rating','Average Cost'], ascending=[False, True])
    return match[['Name','Cuisines','Average Cost','Aggregate Rating']].head(n)

for city in ['Cleveland','Columbus','Cincinnati']:
    print('CITY', city)
    for cuisine in ['American','Mediterranean','Chinese','Italian']:
        print(cuisine)
        print(pick(city,cuisine).to_string(index=False))
    print('---')
